import { DEFAULT_APPEARANCE } from './characters'

/** Where generated/curated avatar GLBs live (design-draft-v2 §5). */
export const AVATAR_MODEL_BASE = '/models/avatars'

/**
 * Shared base body meshes, one per sex. Every race uses the same CC0 MakeHuman
 * base (generated by `tools/avatar-gen/`); race is expressed at runtime through
 * `RACE_PRESETS` (scale now, attachable parts once they are authored).
 */
export const AVATAR_BASES = {
  M: `${AVATAR_MODEL_BASE}/base-M.glb`,
  F: `${AVATAR_MODEL_BASE}/base-F.glb`,
}

/**
 * Part registry: kind → the ids that actually exist as GLBs under
 * `models/avatars/parts/{kind}/{id}.glb` (authored by `tools/avatar-gen/`). A
 * race preset may only reference entries listed here; anything else is dropped
 * by `resolveAvatar` so a missing file can never trip the avatar error boundary.
 *
 * Additive features only for now — pointed ears need a base variant and are not
 * yet authored, so `ears` stays empty. `hair` is player-chosen (not race-fixed)
 * and resolved from `appearance.hairStyle` in `resolveAvatar`.
 */
export const AVATAR_PARTS = {
  ears: [],
  horns: ['dragonborn', 'tiefling'],
  tusks: ['half-orc'],
  tail: ['dragonborn', 'tiefling'],
  hair: ['short', 'ponytail', 'long'],
}

/**
 * The wizard's hair-style choices. An empty value (bald / no hair) is legal and
 * simply attaches no hair part.
 */
export const HAIR_STYLES = [
  { value: '', label: 'None' },
  { value: 'short', label: 'Short' },
  { value: 'ponytail', label: 'Ponytail' },
  { value: 'long', label: 'Long' },
]

/** Human-readable label for a stored `hairStyle` slug (unknown styles read as None). */
export function hairStyleLabel(style) {
  return HAIR_STYLES.find((option) => option.value === (style ?? ''))?.label ?? 'None'
}

/**
 * Per-race presentation: uniform scale factor and the `{ kind, id, socket }`
 * parts to attach at the matching `socket_*` empty. Ears are deferred, so the
 * ear-bearing races carry no parts yet.
 */
export const RACE_PRESETS = {
  human: { scale: 1, parts: [] },
  elf: { scale: 1, parts: [] },
  'half-elf': { scale: 1, parts: [] },
  dwarf: { scale: 0.8, parts: [] },
  gnome: { scale: 0.75, parts: [] },
  halfling: { scale: 0.75, parts: [] },
  'half-orc': { scale: 1.05, parts: [{ kind: 'tusks', id: 'half-orc', socket: 'socket_tusks' }] },
  dragonborn: {
    scale: 1.05,
    parts: [
      { kind: 'horns', id: 'dragonborn', socket: 'socket_horns' },
      { kind: 'tail', id: 'dragonborn', socket: 'socket_tail' },
    ],
  },
  tiefling: {
    scale: 1,
    parts: [
      { kind: 'horns', id: 'tiefling', socket: 'socket_horns' },
      { kind: 'tail', id: 'tiefling', socket: 'socket_tail' },
    ],
  },
}

/** Fallback preset for an unknown/unset race. */
export const DEFAULT_RACE_PRESET = { scale: 1, parts: [] }

/** True when `id` is a registered, existing part of `kind`. */
export function hasAvatarPart(kind, id) {
  return Array.isArray(AVATAR_PARTS[kind]) && AVATAR_PARTS[kind].includes(id)
}

/** Maps the `Sex` enum to the single-letter asset code used in filenames. */
export function avatarSexCode(sex) {
  if (sex === 'MALE') return 'M'
  if (sex === 'FEMALE') return 'F'
  return null
}

/** URL for a part GLB, or null when either half is missing. */
export function avatarPartUrl(kind, id) {
  return kind && id ? `${AVATAR_MODEL_BASE}/parts/${kind}/${id}.glb` : null
}

/**
 * Resolves everything `AvatarCanvas` needs for a race×sex, or null when no base
 * body exists for the sex (the UI then shows the 2D tint swatch). Parts are
 * resolved to `{ socket, url }` entries; missing registry entries are dropped.
 * A registered `appearance.hairStyle` appends the matching hair part at
 * `socket_hair` after the race-feature parts.
 */
export function resolveAvatar(raceIndex, sex, appearance) {
  const code = avatarSexCode(sex)
  const base = code ? AVATAR_BASES[code] ?? null : null
  if (!base) return null
  const preset = RACE_PRESETS[raceIndex] ?? DEFAULT_RACE_PRESET
  const parts = (preset.parts ?? [])
    .filter((part) => part.socket && hasAvatarPart(part.kind, part.id))
    .map((part) => ({
      socket: part.socket,
      url: avatarPartUrl(part.kind, part.id),
    }))
  const hairStyle = appearance?.hairStyle
  if (hasAvatarPart('hair', hairStyle)) {
    parts.push({ socket: 'socket_hair', url: avatarPartUrl('hair', hairStyle) })
  }
  return { base, parts, scale: preset.scale ?? 1 }
}

/**
 * True when the runtime can create a WebGL context. Used to skip mounting the
 * (heavy, code-split) three.js canvas in environments without WebGL (e.g. jsdom
 * tests, or a browser with WebGL disabled) and fall back to the 2D swatch.
 */
export function supportsWebGL() {
  return typeof window !== 'undefined' && typeof window.WebGLRenderingContext !== 'undefined'
}

/**
 * Parents `partRoot` at the named socket inside `root`. Returns true when the
 * socket existed and the part was attached.
 */
export function attachToSocket(root, socketName, partRoot) {
  if (!root || typeof root.getObjectByName !== 'function' || !partRoot) return false
  const socket = root.getObjectByName(socketName)
  if (!socket || typeof socket.add !== 'function') return false
  socket.add(partRoot)
  return true
}

/** CSS colour for a hue slider value; a null/invalid hue falls back to the default tint. */
export function hueCss(hue, fallback = 0) {
  const value = Number.isInteger(hue) ? hue : fallback
  return `hsl(${value} 45% 60%)`
}

/**
 * Recolours a loaded glTF scene from the appearance tints: materials whose name
 * contains `Skin`/`Hair` (case-insensitive) get the chosen hue. Meshes without
 * such materials keep their baked colours. Returns the same root for chaining.
 */
export function applyAvatarTints(root, appearance) {
  if (!root || typeof root.traverse !== 'function') return root
  const skin = hueCss(appearance?.skinTone, DEFAULT_APPEARANCE.skinTone)
  const hair = hueCss(appearance?.hairTone, DEFAULT_APPEARANCE.hairTone)
  root.traverse((node) => {
    if (!node || node.isMesh !== true) return
    const materials = Array.isArray(node.material) ? node.material : [node.material]
    materials.forEach((material) => {
      if (!material || !material.color) return
      const name = String(material.name || '').toLowerCase()
      if (name.includes('skin')) material.color.set(skin)
      else if (name.includes('hair')) material.color.set(hair)
    })
  })
  return root
}
